<?php
declare(strict_types=1);

function admin_shell_start(string $title,array $user,?array $tenant=null,string $active='dashboard'):void{
    global $app;layout_start($title,$tenant,true);$officialLogo=$app->setting('platform_logo',url('assets/fisitapp-logo.webp'));$viewLabel=(($tenant['catalog_label']??'Catálogo')==='Menú')?'Vista cocina':'Vista monitor';
    $groups=$user['role']==='master'?[
        'Plataforma'=>['dashboard'=>'Resumen','empresas'=>'Empresas','planes'=>'Planes y vencimientos','modules'=>'Planes y módulos'],
        'Contenido y análisis'=>['contenido'=>'Web FISITAPP','blog'=>'Blog general','reportes'=>'Reportes'],
        'Sistema'=>['auditoria'=>'Auditoría','configuracion'=>'Configuración','qa'=>'QA del sitio','cache'=>'Caché']
    ]:[
        'Inicio'=>['dashboard'=>'Resumen'],
        'Tienda en línea'=>['pedidos'=>'Pedidos','cocina'=>$viewLabel,'productos'=>'Productos','opciones'=>'Opciones y combos','categorias'=>'Categorías','delivery'=>'Zonas delivery','cupones'=>'Cupones','clientes'=>'Clientes','fidelizacion'=>'Fidelización'],
        'Inventario e impresión'=>['inventario'=>'Inventario','impresion'=>'Impresoras y recibos'],
        'Tienda física'=>['ventas'=>'Ventas','cobro'=>'Cobro','express-pendientes'=>'Express pendientes','turnos'=>'Turnos','compras'=>'Compras','cxc'=>'Cuentas por cobrar','cxp'=>'Cuentas por pagar'],
        'Motorizados y entregas'=>['express'=>'FISITAPP Express','repartidor'=>'Seguimiento de entregas'],
        'Administración'=>['sucursales'=>'Sucursales','reportes'=>'Reportes','usuarios'=>'Equipo','auditoria'=>'Auditoría'],
        'Página y configuración'=>['contenido'=>'Página y promociones','blog'=>'Blog','contactos'=>'Contactos','configuracion'=>'Configuración']
    ];
    if (function_exists('restructure_active_r1') && restructure_active_r1($app)) $groups = restructure_groups_r1($user, $tenant);
    echo '<div class="admin-shell"><aside class="sidebar" data-admin-menu><div class="sidebar-head"><a class="brand admin-brand" href="'.role_home_url_v1($app,$user).'"><img src="'.e($officialLogo).'" alt="FISITAAP">'.($tenant?'<span>'.e($tenant['name']).'</span>':'').'</a><button class="icon-btn admin-menu-toggle" type="button" data-admin-menu-toggle aria-expanded="false" aria-controls="adminMenuLinks" aria-label="Abrir menú del panel"><span aria-hidden="true">☰</span></button></div><nav id="adminMenuLinks" class="sidebar-groups">';$base=$user['role']==='master'?'master':'admin';
    foreach($groups as $groupLabel=>$links){$visible=[];foreach($links as $key=>$label){if(in_array($key,['cobro','express-pendientes'],true)&&($tenant['catalog_label']??'')!=='Menú')continue;if($user['role']!=='master'&&in_array($key,['ventas','cobro','express-pendientes','turnos','compras','cxc','cxp'],true)&&(!$tenant||!physical_store_v14($tenant)))continue;if($key==='roles'&&$user['role']!=='tenant_admin')continue;if($user['role']!=='master'&&!role_can($user['role'],$key))continue;if($user['role']!=='master'&&$tenant&&!module_enabled_v12($app,$tenant,($key==='roles'?'team':section_module_v12($key))))continue;$visible[$key]=$label;}if(!$visible)continue;$opened=isset($visible[$active])||$groupLabel==='Inicio';echo '<details class="nav-group" data-nav-group '.($opened?'open':'').'><summary><span>'.e($groupLabel).'</span><span class="nav-chevron">⌄</span></summary><div class="nav-group-links">';foreach($visible as $key=>$label)echo '<a class="side-link '.($active===$key?'active':'').'" href="'.url($base.($key==='dashboard'?'':'/'.$key)).'">'.e($label).'</a>';echo '</div></details>';}
    echo '</nav><div class="sidebar-foot"><a class="side-link" target="_blank" href="'.url('ayuda?perfil='.($user['role']==='master'?'master':($user['role']==='driver'?'driver':'store'))).'">? Manual de uso</a><span>'.e($user['name']).'</span><form method="post" action="'.url('logout').'">'.csrf_field().'<button class="side-logout">Cerrar sesión</button></form></div></aside><main class="admin-main"><header class="admin-top"><button class="icon-btn admin-mobile-launch" type="button" data-admin-menu-toggle aria-label="Abrir menú">☰</button><div><p class="muted" style="margin:0">'.e($tenant['name']??'Control de plataforma').'</p><h1>'.e($title).'</h1></div><div class="admin-actions">'.($user['role']==='master'?'<form method="post" action="'.url('master/cache').'" onsubmit="return confirm(\'¿Vaciar la caché?\')">'.csrf_field().'<button class="btn btn-light">↻ Caché</button></form>':'').($tenant?'<a class="btn btn-light" target="_blank" href="'.url($tenant['slug']).'">Ver tienda</a>':'').'</div></header>';render_flashes();
}
function admin_shell_end():void{global $app;$u=current_user();if($u&&$u['role']==='tenant_admin')fisichat_widget(false);elseif(function_exists('r2_active')&&r2_active($app))r2_chat_widget($app);echo '</main></div>';layout_end();}
function audit(App $app,?int $tenantId,int $userId,string $action,string $type='',?int $id=null):void{$ip=hash('sha256',($_SERVER['REMOTE_ADDR']??'').$app->config['app_key']);$app->exec('INSERT INTO audit_logs(tenant_id,user_id,action,entity_type,entity_id,ip_hash) VALUES(?,?,?,?,?,?)',[$tenantId,$userId,$action,$type,$id,$ip]);}
function slugify(string $s):string{$s=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s);$s=strtolower(preg_replace('/[^a-zA-Z0-9]+/','-',(string)$s));return trim($s,'-')?:bin2hex(random_bytes(3));}
function store_uploaded_image_v12(string $tmp,string $mime,int $size):string{if($size<=0||$size>5*1024*1024)throw new RuntimeException('Cada imagen debe pesar menos de 5 MB.');$info=@getimagesize($tmp);if(!$info||$info[0]<1||$info[1]<1||($info[0]*$info[1])>30000000)throw new RuntimeException('La imagen no es válida o tiene dimensiones excesivas.');$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Solo se permiten JPG, PNG o WebP.');$relative='uploads/'.date('Y/m');$dir=ROOT_PATH.'/'.$relative;if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('No se pudo crear la carpeta de imágenes.');$base=bin2hex(random_bytes(16));if(function_exists('imagewebp')&&function_exists('imagecreatetruecolor')){$source=match($mime){'image/jpeg'=>@imagecreatefromjpeg($tmp),'image/png'=>@imagecreatefrompng($tmp),'image/webp'=>function_exists('imagecreatefromwebp')?@imagecreatefromwebp($tmp):false,default=>false};if($source){$width=(int)$info[0];$height=(int)$info[1];$ratio=min(1,1440/max($width,$height));$newWidth=max(1,(int)round($width*$ratio));$newHeight=max(1,(int)round($height*$ratio));$canvas=imagecreatetruecolor($newWidth,$newHeight);imagealphablending($canvas,false);imagesavealpha($canvas,true);$transparent=imagecolorallocatealpha($canvas,0,0,0,127);imagefilledrectangle($canvas,0,0,$newWidth,$newHeight,$transparent);imagecopyresampled($canvas,$source,0,0,0,0,$newWidth,$newHeight,$width,$height);$name=$base.'.webp';$ok=imagewebp($canvas,$dir.'/'.$name,76);imagedestroy($canvas);imagedestroy($source);if($ok){@chmod($dir.'/'.$name,0644);return url($relative.'/'.$name);}}}$name=$base.'.'.$allowed[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$name)&&!rename($tmp,$dir.'/'.$name))throw new RuntimeException('No se pudo guardar la imagen.');@chmod($dir.'/'.$name,0644);return url($relative.'/'.$name);}
function upload_image(string $field):?string{if(empty($_FILES[$field]['tmp_name']))return null;$file=$_FILES[$field];if((int)$file['error']!==UPLOAD_ERR_OK)throw new RuntimeException('No se pudo recibir la imagen.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);return store_uploaded_image_v12((string)$file['tmp_name'],(string)$mime,(int)$file['size']);}
function upload_images(string $field,int $limit=6):array{$files=$_FILES[$field]??null;if(!$files||!is_array($files['name']??null))return [];$urls=[];$count=0;foreach($files['name'] as $i=>$original){if(!$original)continue;if(++$count>$limit)throw new RuntimeException('La galería permite un máximo de '.$limit.' imágenes nuevas por vez.');if((int)($files['error'][$i]??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('No se pudo recibir una imagen de la galería.');$tmp=(string)$files['tmp_name'][$i];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$urls[]=store_uploaded_image_v12($tmp,(string)$mime,(int)$files['size'][$i]);}return $urls;}

function master_routes(App $app,string $path):void{
    $u=require_login(['master']);$section=explode('/',$path)[1]??'dashboard';
    if($section==='empresas')master_tenants($app,$u);elseif($section==='reportes')master_reports($app,$u);elseif($section==='blog')master_blog_admin($app,$u);elseif($section==='configuracion'||$section==='contenido')master_settings($app,$u,$section);else master_dashboard($app,$u);
}
function master_dashboard(App $app,array $u):void{$stats=['Empresas activas'=>$app->one("SELECT COUNT(*) n FROM tenants WHERE is_active=1 AND slug NOT IN ('tienda-demo','restaurante-demo')")['n'],'Tiendas suspendidas'=>$app->one("SELECT COUNT(*) n FROM tenants WHERE is_active=0 AND slug NOT IN ('tienda-demo','restaurante-demo')")['n'],'Pedidos totales'=>$app->one("SELECT COUNT(*) n FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE t.slug NOT IN ('tienda-demo','restaurante-demo')")['n'],'Usuarios finales'=>$app->one("SELECT COUNT(DISTINCT o.user_id) n FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE t.slug NOT IN ('tienda-demo','restaurante-demo')")['n']];$recent=$app->all("SELECT o.*,t.name tenant FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE t.slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY o.created_at DESC LIMIT 10");admin_shell_start('Resumen general',$u,null,'dashboard');echo '<div class="grid grid-4">';foreach($stats as $k=>$v)echo '<article class="card stat"><div class="stat-label">'.e($k).'</div><div class="stat-value">'.e((string)$v).'</div></article>';echo '</div><section class="card admin-card" style="margin-top:22px"><h2>Pedidos recientes</h2>';orders_table($recent,true);echo '</section>';admin_shell_end();}
function master_tenants(App $app,array $u):void{
    if(is_post()){verify_csrf();$action=$_POST['action']??'save';try{if($action==='toggle'){$id=(int)$_POST['id'];$app->exec("UPDATE tenants SET is_active=1-is_active WHERE id=? AND slug!='tienda-demo'",[$id]);audit($app,null,$u['id'],'toggle_tenant','tenant',$id);flash('success','Estado de la empresa actualizado.');}else{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=slugify(($_POST['slug']??'')?:$name);$email=strtolower(trim($_POST['admin_email']??''));if(!$name||!preg_match('/^[a-z0-9-]{2,100}$/',$slug))throw new RuntimeException('Nombre o enlace inválido.');$logo=upload_image('logo');if($id){$sql='UPDATE tenants SET name=?,slug=?,email=?,phone=?,whatsapp=?,catalog_label=?,is_listed=?'.($logo?',logo=?':'').' WHERE id=?';$p=[$name,$slug,trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),($_POST['catalog_label']??'')==='Menú'?'Menú':'Catálogo',isset($_POST['is_listed'])?1:0];if($logo)$p[]=$logo;$p[]=$id;$app->exec($sql,$p);audit($app,null,$u['id'],'update_tenant','tenant',$id);}else{if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($_POST['admin_password']??'')<12)throw new RuntimeException('El administrador necesita correo válido y contraseña temporal de 12 caracteres.');$app->db->beginTransaction();$app->exec('INSERT INTO tenants(name,slug,email,phone,whatsapp,catalog_label,logo,is_listed) VALUES(?,?,?,?,?,?,?,?)',[$name,$slug,trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),($_POST['catalog_label']??'')==='Menú'?'Menú':'Catálogo',$logo,isset($_POST['is_listed'])?1:0]);$id=(int)$app->db->lastInsertId();$app->exec('INSERT INTO users(tenant_id,name,email,phone,password_hash,role,force_password_change) VALUES(?,?,?,?,?,?,1)',[$id,trim($_POST['admin_name']??'Administrador'),$email,trim($_POST['phone']??''),password_hash($_POST['admin_password'],PASSWORD_DEFAULT),'tenant_admin']);foreach([['San José centro',2500],['Alrededores',4000]] as $z)$app->exec('INSERT INTO delivery_zones(tenant_id,name,price) VALUES(?,?,?)',[$id,$z[0],$z[1]]);$app->db->commit();audit($app,null,$u['id'],'create_tenant','tenant',$id);}flash('success','Empresa guardada correctamente.');}}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('master/empresas'));}
    $edit=!empty($_GET['edit'])?$app->one("SELECT * FROM tenants WHERE id=? AND slug!='tienda-demo'",[(int)$_GET['edit']]):null;$rows=$app->all("SELECT t.*,(SELECT email FROM users WHERE tenant_id=t.id AND role='tenant_admin' ORDER BY id LIMIT 1) admin_email FROM tenants t WHERE t.slug!='tienda-demo' ORDER BY t.created_at DESC");admin_shell_start('Empresas',$u,null,'empresas');echo '<div class="split"><section class="card admin-card"><h2>'.($edit?'Editar empresa':'Nueva empresa').'</h2><form method="post" enctype="multipart/form-data">'.csrf_field().'<input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div class="form-group"><label>Nombre comercial</label><input class="input" name="name" value="'.e($edit['name']??'').'" required></div><div class="form-group"><label>Enlace</label><div style="display:flex;align-items:center"><span>fisitaap.com/</span><input class="input" name="slug" value="'.e($edit['slug']??'').'" placeholder="se genera automáticamente"></div></div><div class="split"><div class="form-group"><label>WhatsApp pedidos</label><input class="input" name="whatsapp" value="'.e($edit['whatsapp']??'').'" required></div><div class="form-group"><label>Teléfono</label><input class="input" name="phone" value="'.e($edit['phone']??'').'"></div></div><div class="form-group"><label>Correo del negocio</label><input class="input" type="email" name="email" value="'.e($edit['email']??'').'"></div><div class="form-group"><label>Logo</label><input class="input" type="file" name="logo" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>Nombre del catálogo</label><select class="input" name="catalog_label"><option>Catálogo</option><option '.(($edit['catalog_label']??'')==='Menú'?'selected':'').'>Menú</option></select></div><label><input type="checkbox" name="is_listed" '.(($edit['is_listed']??1)?'checked':'').'> Mostrar en directorio</label>';if(!$edit)echo '<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Administrador principal</h3><div class="form-group"><label>Nombre</label><input class="input" name="admin_name" required></div><div class="form-group"><label>Correo de acceso</label><input class="input" type="email" name="admin_email" required></div><div class="form-group"><label>Contraseña temporal</label><input class="input" type="password" name="admin_password" minlength="12" required></div>';echo '<button class="btn btn-block">Guardar empresa</button></form></section><section class="card admin-card"><h2>Empresas creadas</h2><div class="table-wrap"><table class="table"><tr><th>Empresa</th><th>Enlace</th><th>Estado</th><th>Acción</th></tr>';foreach($rows as $r)echo '<tr><td><strong>'.e($r['name']).'</strong><br><small>'.e($r['admin_email']).'</small></td><td><a target="_blank" href="'.url($r['slug']).'">/'.$r['slug'].'</a></td><td><span class="status '.(!$r['is_active']?'status-off':'').'">'.($r['is_active']?'Activa':'Suspendida').'</span></td><td><a class="btn btn-light" href="?edit='.(int)$r['id'].'">Editar</a><form method="post" style="display:inline">'.csrf_field().'<input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="btn '.($r['is_active']?'btn-danger':'btn-accent').'">'.($r['is_active']?'Suspender':'Activar').'</button></form></td></tr>';echo '</table></div></section></div>';admin_shell_end();}
function master_reports(App $app,array $u):void{$rows=$app->all('SELECT t.name,COUNT(o.id) orders_count,COALESCE(SUM(o.total),0) sales,COUNT(DISTINCT o.user_id) customers FROM tenants t LEFT JOIN orders o ON o.tenant_id=t.id GROUP BY t.id ORDER BY sales DESC');admin_shell_start('Reportes globales',$u,null,'reportes');echo '<section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Empresa</th><th>Pedidos</th><th>Ventas</th><th>Clientes</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['orders_count']).'</td><td>'.money((float)$r['sales']).'</td><td>'.e($r['customers']).'</td></tr>';echo '</table></div></section>';admin_shell_end();}
function master_settings(App $app,array $u,string $section):void{if(is_post()){verify_csrf();foreach(['site_name','master_whatsapp','home_title','home_subtitle'] as $k)$app->exec('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$k,trim($_POST[$k]??'')]);flash('success','Configuración guardada.');redirect(url('master/'.$section));}admin_shell_start($section==='contenido'?'Contenido de FISITAPP':'Configuración',$u,null,$section);echo '<section class="card admin-card" style="max-width:760px"><form method="post">'.csrf_field();foreach(['site_name'=>'Nombre de plataforma','master_whatsapp'=>'WhatsApp comercial','home_title'=>'Título principal','home_subtitle'=>'Texto principal'] as $k=>$label)echo '<div class="form-group"><label>'.e($label).'</label><input class="input" name="'.e($k).'" value="'.e($app->setting($k)).'"></div>';echo '<button class="btn">Guardar cambios</button></form></section>';admin_shell_end();}
function master_blog_admin(App $app,array $u):void{if(is_post()){verify_csrf();try{$body=trim($_POST['body']??'');$media=upload_image('media');if(!$body)throw new RuntimeException('Escribe el contenido.');$app->exec('INSERT INTO posts(tenant_id,author_id,body,media_url,media_type,status,published_at) VALUES(NULL,?,?,?,?,"published",NOW())',[$u['id'],$body,$media,$media?'image':null]);flash('success','Publicación general creada.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect(url('master/blog'));}$rows=$app->all('SELECT * FROM posts WHERE tenant_id IS NULL ORDER BY created_at DESC');admin_shell_start('Blog general',$u,null,'blog');echo '<div class="split"><section class="card admin-card"><form method="post" enctype="multipart/form-data">'.csrf_field().'<div class="form-group"><label>Publicación</label><textarea class="input" name="body" required maxlength="5000"></textarea></div><div class="form-group"><label>Imagen</label><input class="input" type="file" name="media" accept="image/jpeg,image/png,image/webp"></div><button class="btn btn-block">Publicar</button></form></section><section>';foreach($rows as $p)echo '<article class="card post">'.($p['media_url']?'<img class="post-media" src="'.e($p['media_url']).'">':'').'<div class="post-body">'.nl2br(e($p['body'])).'</div></article>';echo '</section></div>';admin_shell_end();}

function tenant_admin_routes(App $app,string $path):void{
    $u=require_login(['tenant_admin','manager','editor']);$t=$app->one('SELECT * FROM tenants WHERE id=?',[$u['tenant_id']]);if(!$t)exit('Empresa no disponible');$section=explode('/',$path)[1]??'dashboard';
    $allowed=['dashboard','pedidos','cocina','repartidor','productos','opciones','categorias','delivery','cupones','clientes','contenido','blog','reportes','usuarios','configuracion'];if(!in_array($section,$allowed,true))$section='dashboard';require_section_permission($u,$section);
    if($section==='dashboard')tenant_dashboard($app,$u,$t);elseif($section==='pedidos')tenant_orders_v3($app,$u,$t);elseif($section==='cocina')tenant_kitchen_v4($app,$u,$t);elseif($section==='repartidor')tenant_delivery_board_v4($app,$u,$t);elseif($section==='productos')tenant_products_v5($app,$u,$t);elseif($section==='opciones')tenant_product_options_v5($app,$u,$t);elseif(in_array($section,['categorias','delivery','cupones'],true))tenant_simple_module_v3($app,$u,$t,$section);elseif($section==='reportes')tenant_reports($app,$u,$t);elseif($section==='contenido')tenant_content_admin_v3($app,$u,$t);elseif($section==='blog')tenant_blog_admin($app,$u,$t);elseif($section==='configuracion')tenant_settings($app,$u,$t);elseif($section==='clientes')tenant_customers($app,$u,$t);else tenant_team($app,$u,$t);
}
function tenant_dashboard(App $app,array $u,array $t):void
{
    $tid=(int)$t['id'];

    // Keep the dashboard's independent counters in one database round trip.
    // This matters on shared hosting where each MySQL round trip can be slow.
    $metrics=$app->one("SELECT v.*,o.*,
      (SELECT COUNT(DISTINCT user_id) FROM tenant_customers WHERE tenant_id=?) customers,
      (SELECT COUNT(*) FROM products WHERE tenant_id=? AND status='active') products,
      (SELECT COUNT(*) FROM product_inventory WHERE tenant_id=? AND track_stock=1 AND (quantity-reserved_quantity)<=GREATEST(min_stock,reorder_point)) low_stock
      FROM (SELECT
        COUNT(CASE WHEN created_at>=CURDATE() THEN 1 END) sales_today_n,
        COALESCE(SUM(CASE WHEN created_at>=CURDATE() THEN total ELSE 0 END),0) sales_today_total,
        COALESCE(AVG(CASE WHEN created_at>=CURDATE() THEN total END),0) sales_today_avg,
        COALESCE(SUM(CASE WHEN created_at>=DATE_SUB(CURDATE(),INTERVAL 1 DAY) AND created_at<CURDATE() THEN total ELSE 0 END),0) sales_yesterday_total,
        COUNT(CASE WHEN created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') THEN 1 END) month_sales_n,
        COALESCE(SUM(CASE WHEN created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') THEN total ELSE 0 END),0) month_sales_total
        FROM sales WHERE tenant_id=? AND status IN ('completed','credit')
          AND created_at>=LEAST(DATE_FORMAT(CURDATE(),'%Y-%m-01'),DATE_SUB(CURDATE(),INTERVAL 1 DAY))
          AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY)) v
      CROSS JOIN (SELECT COUNT(*) orders_today_n,COALESCE(SUM(total),0) orders_today_total
        FROM orders WHERE tenant_id=? AND status!='cancelled' AND created_at>=CURDATE()
          AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY)) o",
      array_fill(0,5,$tid));
    $salesToday=['n'=>(int)($metrics['sales_today_n']??0),'total'=>(float)($metrics['sales_today_total']??0),'avg_ticket'=>(float)($metrics['sales_today_avg']??0)];
    $salesYesterday=['total'=>(float)($metrics['sales_yesterday_total']??0)];
    $monthSales=['n'=>(int)($metrics['month_sales_n']??0),'total'=>(float)($metrics['month_sales_total']??0)];
    $ordersToday=['n'=>(int)($metrics['orders_today_n']??0),'total'=>(float)($metrics['orders_today_total']??0)];
    $customers=(int)($metrics['customers']??0);
    $products=(int)($metrics['products']??0);
    $lowStock=(int)($metrics['low_stock']??0);

    $todayTotal=(float)($salesToday['total']??0);
    $yesterdayTotal=(float)($salesYesterday['total']??0);
    $change=$yesterdayTotal>0?(($todayTotal-$yesterdayTotal)/$yesterdayTotal)*100:null;

    $sales7=$app->all("SELECT DATE(created_at) day,COALESCE(SUM(total),0) total,COUNT(*) n FROM sales WHERE tenant_id=? AND status IN ('completed','credit') AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY) GROUP BY DATE(created_at) ORDER BY day",[$tid]);
    $map=[];foreach($sales7 as $row)$map[$row['day']]=$row;
    $chart=[];$maxSale=0;
    for($i=6;$i>=0;$i--){
        $d=date('Y-m-d',strtotime("-$i day"));
        $row=$map[$d]??['day'=>$d,'total'=>0,'n'=>0];
        $row['total']=(float)$row['total'];$row['n']=(int)$row['n'];
        $maxSale=max($maxSale,$row['total']);$chart[]=$row;
    }

    $topProducts=$app->all("SELECT si.product_name,ROUND(SUM(si.quantity),2) qty,ROUND(SUM(si.line_subtotal+si.line_tax),2) revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.tenant_id=? AND s.status IN ('completed','credit') AND s.created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') AND s.created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY) GROUP BY si.product_id,si.product_name ORDER BY qty DESC,revenue DESC LIMIT 5",[$tid]);

    $payments=$app->all("SELECT payment_method,ROUND(SUM(total),2) total FROM sales WHERE tenant_id=? AND status IN ('completed','credit') AND created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY) GROUP BY payment_method ORDER BY total DESC LIMIT 5",[$tid]);
    $paymentTotal=0;foreach($payments as $p)$paymentTotal+=(float)$p['total'];

    $recent=$app->all('SELECT * FROM orders WHERE tenant_id=? ORDER BY created_at DESC LIMIT 8',[$tid]);

    admin_shell_start('Resumen',$u,$t,'dashboard');

    echo '<section class="dash-welcome">';
    echo '<div><span class="dash-kicker">PANEL DEL NEGOCIO</span><h2>Así se mueve '.e($t['name']).'</h2><p>Una vista rápida de lo importante, actualizada con los datos registrados en FISITAAP.</p></div>';
    echo '<div class="dash-date"><small>Hoy</small><strong>'.e(date('d/m/Y')).'</strong></div>';
    echo '</section>';

    echo '<section class="dash-kpis">';
    echo '<article class="dash-kpi"><span class="dash-icon">₡</span><div><small>Ventas hoy</small><strong>'.money($todayTotal).'</strong><em class="'.($change!==null&&$change<0?'down':'up').'">'.($change===null?'Sin comparación':(($change>=0?'↑ ':'↓ ').number_format(abs($change),1).'% vs ayer')).'</em></div></article>';
    echo '<article class="dash-kpi"><span class="dash-icon">↗</span><div><small>Ventas del mes</small><strong>'.money((float)($monthSales['total']??0)).'</strong><em>'.(int)($monthSales['n']??0).' transacciones</em></div></article>';
    echo '<article class="dash-kpi"><span class="dash-icon">◎</span><div><small>Pedidos online hoy</small><strong>'.(int)($ordersToday['n']??0).'</strong><em>'.money((float)($ordersToday['total']??0)).'</em></div></article>';
    echo '<article class="dash-kpi"><span class="dash-icon">◇</span><div><small>Ticket promedio hoy</small><strong>'.money((float)($salesToday['avg_ticket']??0)).'</strong><em>'.(int)($salesToday['n']??0).' ventas</em></div></article>';
    echo '</section>';

    echo '<section class="dash-grid-main">';
    echo '<article class="card dash-chart-card"><div class="dash-card-head"><div><small>ÚLTIMOS 7 DÍAS</small><h3>Movimiento de ventas</h3></div><strong>'.money(array_sum(array_column($chart,'total'))).'</strong></div>';
    echo '<div class="dash-bars">';
    foreach($chart as $row){
        $pct=$maxSale>0?max(5,round(($row['total']/$maxSale)*100)):5;
        echo '<div class="dash-bar-col" title="'.e(date('d/m',strtotime($row['day'])).' · '.money($row['total'])).'"><div class="dash-bar-value">'.($row['total']>0?e(money($row['total'])):'').'</div><div class="dash-bar-track"><i style="height:'.$pct.'%"></i></div><span>'.e(ui_label_qa(date('D',strtotime($row['day'])))).'</span><small>'.e(date('d/m',strtotime($row['day']))).'</small></div>';
    }
    echo '</div></article>';

    echo '<article class="card dash-side-card"><div class="dash-card-head"><div><small>ESTE MES</small><h3>Productos destacados</h3></div><a href="'.url('admin/reportes').'">Ver reportes</a></div>';
    if($topProducts){
        echo '<div class="dash-ranking">';
        $rankMax=max(1,(float)$topProducts[0]['qty']);
        foreach($topProducts as $i=>$p){
            $pct=max(4,round(((float)$p['qty']/$rankMax)*100));
            echo '<div class="dash-rank-row"><span class="dash-rank-number">'.($i+1).'</span><div><strong>'.e($p['product_name']).'</strong><small>'.e((string)$p['qty']).' unidades · '.e(money((float)$p['revenue'])).'</small><div class="dash-progress"><i style="width:'.$pct.'%"></i></div></div></div>';
        }
        echo '</div>';
    }else echo '<div class="dash-empty">Aún no hay ventas de productos registradas este mes.</div>';
    echo '</article>';
    echo '</section>';

    echo '<section class="dash-grid-secondary">';
    echo '<article class="card dash-mini-card"><div class="dash-card-head"><div><small>ESTADO GENERAL</small><h3>Tu negocio</h3></div></div><div class="dash-facts">';
    echo '<div><span>Clientes</span><strong>'.$customers.'</strong></div>';
    echo '<div><span>Productos activos</span><strong>'.$products.'</strong></div>';
    echo '<div><span>Stock bajo</span><strong class="'.($lowStock>0?'warn':'').'">'.$lowStock.'</strong></div>';
    echo '<div><span>Pedidos hoy</span><strong>'.(int)($ordersToday['n']??0).'</strong></div>';
    echo '</div></article>';

    echo '<article class="card dash-mini-card"><div class="dash-card-head"><div><small>ESTE MES</small><h3>Formas de pago</h3></div></div>';
    if($payments){
        echo '<div class="dash-payments">';
        foreach($payments as $p){
            $pct=$paymentTotal>0?round(((float)$p['total']/$paymentTotal)*100):0;
            echo '<div><div><span>'.e($p['payment_method']?:'Sin definir').'</span><strong>'.$pct.'%</strong></div><div class="dash-progress"><i style="width:'.$pct.'%"></i></div></div>';
        }
        echo '</div>';
    }else echo '<div class="dash-empty">Sin ventas registradas este mes.</div>';
    echo '</article>';
    echo '</section>';

    echo '<section class="card admin-card dash-recent"><div class="dash-card-head"><div><small>ACTIVIDAD RECIENTE</small><h3>Pedidos recientes</h3></div><a href="'.url('admin/pedidos').'">Ver todos</a></div>';
    orders_table($recent);
    echo '</section>';

    admin_shell_end();
}
function orders_table(array $rows,bool $master=false):void{echo '<div class="table-wrap"><table class="table"><tr><th>Pedido</th>'.($master?'<th>Empresa</th>':'').'<th>Cliente</th><th>Total</th><th>Estado</th><th>Fecha</th></tr>';foreach($rows as $r)echo '<tr><td>#'.e($r['order_number']).'</td>'.($master?'<td>'.e($r['tenant']).'</td>':'').'<td>'.e($r['customer_name']).'</td><td>'.money((float)$r['total']).'</td><td><span class="status">'.e(ui_label_qa((string)$r['status'])).'</span></td><td>'.e(date('d/m/Y H:i',strtotime($r['created_at']))).'</td></tr>';echo '</table></div>';}

function tenant_orders(App $app,array $u,array $t):void{if(is_post()){verify_csrf();$status=$_POST['status']??'';$allowed=['new','confirmed','preparing','ready','sent','delivered','cancelled'];if(in_array($status,$allowed,true)){order_status_qa($app,(int)$t['id'],(int)$_POST['id'],$status,(int)$u['id']);audit($app,$t['id'],$u['id'],'update_order','order',(int)$_POST['id']);flash('success','Pedido actualizado.');}redirect(url('admin/pedidos'));}$status=$_GET['status']??'';$params=[$t['id']];$sql='SELECT * FROM orders WHERE tenant_id=?';if($status){$sql.=' AND status=?';$params[]=$status;}$sql.=' ORDER BY created_at DESC LIMIT 300';$rows=$app->all($sql,$params);admin_shell_start('Pedidos',$u,$t,'pedidos');echo '<div class="chips" style="margin-bottom:18px"><a class="chip '.(!$status?'active':'').'" href="'.url('admin/pedidos').'">Todos</a>';foreach(['new'=>'Nuevos','confirmed'=>'Confirmados','preparing'=>'Preparando','ready'=>'Listos','delivered'=>'Entregados','cancelled'=>'Cancelados'] as $k=>$v)echo '<a class="chip '.($status===$k?'active':'').'" href="?status='.$k.'">'.$v.'</a>';echo '</div><section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Pedido</th><th>Cliente</th><th>Teléfono</th><th>Total</th><th>Pago</th><th>Estado</th><th>Fecha</th></tr>';foreach($rows as $r){echo '<tr><td>#'.e($r['order_number']).'</td><td>'.e($r['customer_name']).'</td><td>'.e($r['customer_phone']).'</td><td>'.money((float)$r['total']).'</td><td>'.e($r['payment_method']).'</td><td><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$r['id'].'"><select class="input" name="status" onchange="this.form.submit()">';foreach(['new'=>'Nuevo','confirmed'=>'Confirmado','preparing'=>'Preparando','ready'=>'Listo','sent'=>'Enviado','delivered'=>'Entregado','cancelled'=>'Cancelado'] as $k=>$v)echo '<option value="'.$k.'" '.($r['status']===$k?'selected':'').'>'.$v.'</option>';echo '</select></form></td><td>'.e(date('d/m/Y H:i',strtotime($r['created_at']))).'</td></tr>';}echo '</table></div></section>';admin_shell_end();}

function tenant_products(App $app,array $u,array $t):void{if(is_post()){verify_csrf();try{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Escribe el nombre del producto.');$image=upload_image('image');$vals=[$name,slugify(($_POST['slug']??'')?:$name),($_POST['category_id']??'')?(int)$_POST['category_id']:null,trim($_POST['description']??''),trim($_POST['characteristics']??''),(float)$_POST['price'],($_POST['sale_price']??'')!==''?(float)$_POST['sale_price']:null,(float)$_POST['tax_rate'],trim($_POST['unit_label']??'unidad'),(float)$_POST['min_qty'],(float)$_POST['qty_step'],(int)$_POST['decimals'],trim($_POST['badge']??''),in_array($_POST['status']??'', ['active','hidden','sold_out'],true)?$_POST['status']:'active'];if($id){$sql='UPDATE products SET name=?,slug=?,category_id=?,description=?,characteristics=?,price=?,sale_price=?,tax_rate=?,unit_label=?,min_qty=?,qty_step=?,decimals=?,badge=?,status=?'.($image?',image=?':'').' WHERE id=? AND tenant_id=?';if($image)$vals[]=$image;$vals[]=$id;$vals[]=$t['id'];$app->exec($sql,$vals);audit($app,$t['id'],$u['id'],'update_product','product',$id);}else{$vals=array_merge([$t['id']],$vals,[$image]);$app->exec('INSERT INTO products(tenant_id,name,slug,category_id,description,characteristics,price,sale_price,tax_rate,unit_label,min_qty,qty_step,decimals,badge,status,image) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$vals);audit($app,$t['id'],$u['id'],'create_product','product',(int)$app->db->lastInsertId());}flash('success','Producto guardado.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect(url('admin/productos'));}$edit=!empty($_GET['edit'])?$app->one('SELECT * FROM products WHERE id=? AND tenant_id=?',[(int)$_GET['edit'],$t['id']]):null;$cats=$app->all('SELECT * FROM categories WHERE tenant_id=? ORDER BY name',[$t['id']]);$rows=$app->all('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=? ORDER BY p.created_at DESC',[$t['id']]);admin_shell_start('Productos',$u,$t,'productos');echo '<div class="split"><section class="card admin-card"><h2>'.($edit?'Editar':'Nuevo').' producto</h2><form method="post" enctype="multipart/form-data">'.csrf_field().'<input type="hidden" name="id" value="'.(int)($edit['id']??0).'">'.field('Nombre','name',$edit['name']??'',true).'<div class="form-group"><label>Categoría</label><select class="input" name="category_id"><option value="">Sin categoría</option>';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'" '.(($edit['category_id']??0)==$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></div><div class="form-group"><label>Descripción</label><textarea class="input" name="description">'.e($edit['description']??'').'</textarea></div><div class="form-group"><label>Características</label><textarea class="input" name="characteristics" placeholder="Una por línea">'.e($edit['characteristics']??'').'</textarea></div><div class="split">'.field('Precio unitario','price',$edit['price']??'0',true,'number','0.01').field('Precio promoción','sale_price',$edit['sale_price']??'',false,'number','0.01').'</div><div class="split">'.field('IVA %','tax_rate',$edit['tax_rate']??'0',true,'number','0.01').field('Unidad','unit_label',$edit['unit_label']??'unidad',true).'</div><div class="split">'.field('Cantidad mínima','min_qty',$edit['min_qty']??'1',true,'number','0.001').field('Incremento','qty_step',$edit['qty_step']??'1',true,'number','0.001').'</div><div class="split">'.field('Decimales','decimals',$edit['decimals']??'0',true,'number','1').field('Etiqueta','badge',$edit['badge']??'').'</div><div class="form-group"><label>Imagen</label><input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>Estado</label><select class="input" name="status">';foreach(['active'=>'Activo','hidden'=>'Oculto','sold_out'=>'Agotado'] as $k=>$v)echo '<option value="'.$k.'" '.(($edit['status']??'active')===$k?'selected':'').'>'.$v.'</option>';echo '</select></div><button class="btn btn-block">Guardar producto</button></form></section><section class="card admin-card"><h2>Catálogo</h2><div class="table-wrap"><table class="table"><tr><th>Producto</th><th>Precio</th><th>IVA</th><th>Estado</th><th></th></tr>';foreach($rows as $r)echo '<tr><td><strong>'.e($r['name']).'</strong><br><small>'.e($r['category']??'').'</small></td><td>'.money((float)$r['price']).'</td><td>'.e($r['tax_rate']).'%</td><td><span class="status">'.e(ui_label_qa((string)$r['status'])).'</span></td><td><a class="btn btn-light" href="?edit='.(int)$r['id'].'">Editar</a></td></tr>';echo '</table></div></section></div>';admin_shell_end();}

function field(string $label,string $name,mixed $value='',bool $required=false,string $type='text',string $step=''):string{static $sequence=0;$id='fisitaap-field-'.(++$sequence);return '<div class="form-group"><label for="'.$id.'">'.e($label).'</label><input id="'.$id.'" class="input" type="'.e($type).'" name="'.e($name).'" value="'.e((string)$value).'" '.($required?'required':'').' '.($step?'step="'.e($step).'"':'').'></div>';}

function tenant_simple_module(App $app,array $u,array $t,string $module):void{$meta=['categorias'=>['Categorías','categories',['name'=>'Nombre','sort_order'=>'Orden']], 'delivery'=>['Zonas de delivery','delivery_zones',['name'=>'Zona','price'=>'Precio','min_order'=>'Compra mínima']], 'cupones'=>['Cupones','coupons',['code'=>'Código','type'=>'Tipo','value'=>'Valor','min_order'=>'Compra mínima','max_uses'=>'Usos máximos','starts_at'=>'Inicio','ends_at'=>'Fin']]][$module];[$title,$table,$fields]=$meta;if(is_post()){verify_csrf();try{$cols=[];$vals=[];foreach($fields as $k=>$label){$v=trim($_POST[$k]??'');if($k==='code')$v=strtoupper($v);if($k==='type')$v=$v==='fixed'?'fixed':'percent';if(in_array($k,['price','min_order','value'],true))$v=(float)$v;if(in_array($k,['sort_order','max_uses'],true))$v=$v===''?null:(int)$v;if(in_array($k,['starts_at','ends_at'],true))$v=$v?str_replace('T',' ',$v).':00':null;$cols[]=$k;$vals[]=$v;}if($table==='categories'){$cols[]='slug';$vals[]=slugify((string)$_POST['name']);}$sql='INSERT INTO '.$table.' (tenant_id,'.implode(',',$cols).') VALUES (?,'.implode(',',array_fill(0,count($cols),'?')).')';$app->exec($sql,array_merge([$t['id']],$vals));flash('success',$title.' actualizado.');}catch(Throwable $e){flash('error','No se pudo guardar. Verifica que no esté duplicado.');}redirect(url('admin/'.$module));}$rows=$app->all("SELECT * FROM $table WHERE tenant_id=? ORDER BY id DESC",[$t['id']]);admin_shell_start($title,$u,$t,$module);echo '<div class="split"><section class="card admin-card"><h2>Agregar</h2><form method="post">'.csrf_field();foreach($fields as $k=>$label){if($k==='type')echo '<div class="form-group"><label>Tipo</label><select class="input" name="type"><option value="percent">Porcentaje</option><option value="fixed">Monto fijo</option></select></div>';else echo field($label,$k,'',in_array($k,['name','code','price','value'],true),in_array($k,['price','min_order','value','sort_order','max_uses'],true)?'number':(in_array($k,['starts_at','ends_at'],true)?'datetime-local':'text'),in_array($k,['price','min_order','value'],true)?'0.01':'1');}echo '<button class="btn btn-block">Agregar</button></form></section><section class="card admin-card"><h2>Registros</h2><div class="table-wrap"><table class="table"><tr>';foreach($fields as $label)echo '<th>'.e($label).'</th>';echo '<th>Estado</th></tr>';foreach($rows as $r){echo '<tr>';foreach(array_keys($fields) as $k)echo '<td>'.e((string)($r[$k]??'')).'</td>';echo '<td><span class="status '.(!$r['is_active']?'status-off':'').'">'.($r['is_active']?'Activo':'Inactivo').'</span></td></tr>';}echo '</table></div></section></div>';admin_shell_end();}

function tenant_reports(App $app,array $u,array $t):void{$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$tot=$app->one("SELECT COUNT(*) orders_count,COALESCE(SUM(total),0) sales,COALESCE(AVG(total),0) avg_ticket,COUNT(DISTINCT user_id) customers FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status!='cancelled'",[$t['id'],$from,$to]);$products=$app->all("SELECT oi.product_name,SUM(oi.quantity) qty,SUM(oi.line_subtotal+oi.line_tax) total FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.tenant_id=? AND DATE(o.created_at) BETWEEN ? AND ? AND o.status!='cancelled' GROUP BY oi.product_name ORDER BY total DESC LIMIT 20",[$t['id'],$from,$to]);admin_shell_start('Reportes y KPI',$u,$t,'reportes');echo '<form class="card admin-card" method="get"><div class="split">'.field('Desde','from',$from,true,'date').field('Hasta','to',$to,true,'date').'</div><button class="btn">Filtrar</button></form><div class="grid grid-4" style="margin-top:20px">';foreach(['Pedidos'=>$tot['orders_count'],'Ventas'=>money((float)$tot['sales']),'Ticket promedio'=>money((float)$tot['avg_ticket']),'Clientes únicos'=>$tot['customers']] as $k=>$v)echo '<article class="card stat"><div class="stat-label">'.e($k).'</div><div class="stat-value">'.e((string)$v).'</div></article>';echo '</div><section class="card admin-card" style="margin-top:20px"><h2>Productos más vendidos</h2><table class="table"><tr><th>Producto</th><th>Cantidad</th><th>Total</th></tr>';foreach($products as $p)echo '<tr><td>'.e($p['product_name']).'</td><td>'.e($p['qty']).'</td><td>'.money((float)$p['total']).'</td></tr>';echo '</table></section>';admin_shell_end();}

function tenant_content_admin(App $app,array $u,array $t):void{if(is_post()){verify_csrf();try{$image=upload_image('image');$section=in_array($_POST['section_key']??'',['home_slider','catalog_slider','home_block'],true)?$_POST['section_key']:'home_block';$count=$app->one('SELECT COUNT(*) n FROM tenant_content WHERE tenant_id=? AND section_key=?',[$t['id'],$section])['n'];$limit=$section==='home_block'?3:3;if($count>=$limit)throw new RuntimeException('Esta sección ya tiene sus tres elementos.');$app->exec('INSERT INTO tenant_content(tenant_id,section_key,title,body,image,button_text,button_url,sort_order) VALUES(?,?,?,?,?,?,?,?)',[$t['id'],$section,trim($_POST['title']??''),trim($_POST['body']??''),$image,trim($_POST['button_text']??''),trim($_POST['button_url']??''),(int)$_POST['sort_order']]);audit($app,$t['id'],$u['id'],'create_content','content',(int)$app->db->lastInsertId());flash('success','Contenido agregado.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect(url('admin/contenido'));}$rows=$app->all('SELECT * FROM tenant_content WHERE tenant_id=? ORDER BY section_key,sort_order',[$t['id']]);admin_shell_start('Página y slider',$u,$t,'contenido');echo '<div class="split"><section class="card admin-card"><h2>Agregar bloque</h2><form method="post" enctype="multipart/form-data">'.csrf_field().'<div class="form-group"><label>Ubicación</label><select class="input" name="section_key"><option value="home_slider">Slider de inicio</option><option value="catalog_slider">Slider de promociones</option><option value="home_block">Bloque informativo</option></select></div>'.field('Título','title','',true).'<div class="form-group"><label>Texto</label><textarea class="input" name="body"></textarea></div><div class="form-group"><label>Imagen</label><input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div>'.field('Texto del botón','button_text').field('Enlace del botón','button_url').field('Orden','sort_order','0',true,'number','1').'<button class="btn btn-block">Agregar contenido</button></form></section><section class="card admin-card"><h2>Contenido actual</h2>';foreach($rows as $r)echo '<article style="display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)">'.($r['image']?'<img src="'.e($r['image']).'" style="width:100px;height:70px;object-fit:cover;border-radius:10px">':'').'<div><span class="tag">'.e($r['section_key']).'</span><strong style="display:block">'.e($r['title']).'</strong><small class="muted">'.e($r['body']).'</small></div></article>';echo '</section></div>';admin_shell_end();}

function tenant_blog_admin(App $app,array $u,array $t):void{if(is_post()){verify_csrf();$body=trim($_POST['body']??'');if($body){$media=upload_image('media');$url=$media?:trim($_POST['media_url']??'');$type=$media?'image':($url?'link':null);$app->exec('INSERT INTO posts(tenant_id,author_id,body,media_url,media_type,status,published_at) VALUES(?,?,?,?,?,"published",NOW())',[$t['id'],$u['id'],$body,$url?:null,$type]);flash('success','Publicación creada.');}redirect(url('admin/blog'));}$rows=$app->all('SELECT * FROM posts WHERE tenant_id=? ORDER BY created_at DESC',[$t['id']]);admin_shell_start('Blog',$u,$t,'blog');echo '<div class="split"><section class="card admin-card"><h2>Nueva publicación</h2><form method="post" enctype="multipart/form-data">'.csrf_field().'<div class="form-group"><label>Texto</label><textarea class="input" name="body" required maxlength="5000"></textarea></div><div class="form-group"><label>Imagen</label><input class="input" type="file" name="media" accept="image/jpeg,image/png,image/webp"></div>'.field('Enlace de video o contenido','media_url').'<button class="btn btn-block">Publicar</button></form></section><section><h2>Publicaciones</h2>';foreach($rows as $p)echo '<article class="card post">'.($p['media_url']&&$p['media_type']==='image'?'<img class="post-media" src="'.e($p['media_url']).'">':'').'<div class="post-body">'.nl2br(e($p['body'])).'</div></article>';echo '</section></div>';admin_shell_end();}

