',$t['offline_message']).'</div><div class="split"><div class="form-group"><label>Color principal</label><input class="input" type="color" name="primary_color" value="'.e($t['primary_color']).'"></div><div class="form-group"><label>Color secundario</label><input class="input" type="color" name="accent_color" value="'.e($t['accent_color']).'"></div></div><button class="btn">Guardar configuración</button></form></section>';admin_shell_end();}

