function tenant_orders_v3(App $app,array $u,array $t):void
{
    if(is_post()){
        verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');
        if($id&&in_array($status,['new','confirmed','preparing','ready','sent','delivered','cancelled'],true)){
            order_status_qa($app,(int)$t['id'],$id,$status,(int)$u['id']);
            audit($app,$t['id'],$u['id'],'update_order','order',$id);flash('success','Pedido actualizado.');
        }
        redirect(url('admin/pedidos'.(!empty($_POST['return_view'])?'?view='.$id:'')));
    }
    $view=(int)($_GET['view']??0);
    if($view){
        $order=$app->one('SELECT o.*,z.name zone_name,u.email customer_email FROM orders o LEFT JOIN delivery_zones z ON z.id=o.delivery_zone_id LEFT JOIN users u ON u.id=o.user_id WHERE o.id=? AND o.tenant_id=?',[$view,$t['id']]);
        if(!$order){http_response_code(404);simple_error('Pedido no encontrado','El pedido no pertenece a esta empresa.');return;}
        $items=$app->all('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$view]);
        admin_shell_start('Pedido #'.$order['order_number'],$u,$t,'pedidos');
        echo '<p><a class="btn btn-light" href="'.url('admin/pedidos').'">← Volver a pedidos</a></p><div class="split"><section class="card admin-card"><h2>Cliente</h2><p><strong>'.e($order['customer_name']).'</strong><br>'.e($order['customer_email']).'<br>'.e($order['customer_phone']).(!empty($order['customer_id_number'])?'<br>Cédula: '.e($order['customer_id_number']):'').'</p><h3>Entrega</h3><p>'.e($order['delivery_type']).' · '.e($order['zone_name']??'Sin zona').'</p><p>'.nl2br(e($order['address'])).(!empty($order['address_reference'])?'<br><strong>Referencia:</strong> '.nl2br(e($order['address_reference'])):'').'</p>'.(!empty($order['scheduled_at'])?'<p><strong>Programado:</strong> '.e(date('d/m/Y H:i',strtotime($order['scheduled_at']))).'</p>':'').'<h3>Notas</h3><p>'.nl2br(e($order['notes']?:'Sin notas')).'</p></section><section class="card admin-card"><h2>Resumen</h2><p>Pago: <strong>'.e($order['payment_method']).'</strong></p><p>Cupón: '.e($order['coupon_code']?:'Sin cupón').'</p><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$order['id'].'"><input type="hidden" name="return_view" value="1"><select class="input" name="status">';
        foreach(['new'=>'Nuevo','confirmed'=>'Confirmado','preparing'=>'Preparando','ready'=>'Listo','sent'=>'Enviado','delivered'=>'Entregado','cancelled'=>'Cancelado'] as $key=>$label)echo '<option value="'.$key.'" '.($order['status']===$key?'selected':'').'>'.$label.'</option>';
        echo '</select><button class="btn btn-block" style="margin-top:10px">Actualizar estado</button></form></section></div><section class="card admin-card" style="margin-top:20px"><h2>Productos</h2><div class="table-wrap"><table class="table"><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th><th>IVA</th></tr>';
        foreach($items as $item)echo '<tr><td>'.e($item['product_name']).order_item_details_html($item).'</td><td>'.e($item['quantity']).' '.e($item['unit_label']).'</td><td>'.money((float)$item['unit_price']).'</td><td>'.money((float)$item['line_subtotal']).'</td><td>'.money((float)$item['line_tax']).'</td></tr>';
        echo '</table></div><div class="order-totals"><p>Subtotal <strong>'.money((float)$order['subtotal']).'</strong></p><p>IVA <strong>'.money((float)$order['tax_total']).'</strong></p><p>Descuento <strong>-'.money((float)$order['discount_total']).'</strong></p><p>Entrega <strong>'.money((float)$order['delivery_total']).'</strong></p><p class="total">Total <strong>'.money((float)$order['total']).'</strong></p></div></section>';admin_shell_end();return;
    }
    $status=(string)($_GET['status']??'');$page=max(1,(int)($_GET['page']??1));$limit=50;$offset=($page-1)*$limit;$params=[$t['id']];$sql='SELECT * FROM orders WHERE tenant_id=?';if(in_array($status,['new','confirmed','preparing','ready','sent','delivered','cancelled'],true)){$sql.=' AND status=?';$params[]=$status;}else{$status='';}$sql.=" ORDER BY created_at DESC LIMIT $limit OFFSET $offset";$rows=$app->all($sql,$params);
    admin_shell_start('Pedidos',$u,$t,'pedidos');echo '<div class="chips" style="margin-bottom:18px"><a class="chip '.(!$status?'active':'').'" href="'.url('admin/pedidos').'">Todos</a>';foreach(['new'=>'Nuevos','confirmed'=>'Confirmados','preparing'=>'Preparando','ready'=>'Listos','sent'=>'Enviados','delivered'=>'Entregados','cancelled'=>'Cancelados'] as $key=>$label)echo '<a class="chip '.($status===$key?'active':'').'" href="?status='.$key.'">'.$label.'</a>';echo '</div><section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Estado</th><th>Fecha</th><th></th></tr>';
    foreach($rows as $order)echo '<tr><td>#'.e($order['order_number']).'</td><td>'.e($order['customer_name']).'<br><small>'.e($order['customer_phone']).'</small></td><td>'.money((float)$order['total']).'</td><td>'.e($order['payment_method']).'</td><td><span class="status">'.e(ui_label_qa((string)$order['status'])).'</span></td><td>'.e(date('d/m/Y H:i',strtotime($order['created_at']))).'</td><td><a class="btn btn-light" href="?view='.(int)$order['id'].'">Ver detalle</a></td></tr>';
    echo '</table></div></section><div class="pagination"><a class="btn btn-light" href="?page='.max(1,$page-1).($status?'&status='.$status:'').'">Anterior</a><span>Página '.$page.'</span>'.(count($rows)===$limit?'<a class="btn btn-light" href="?page='.($page+1).($status?'&status='.$status:'').'">Siguiente</a>':'').'</div>';admin_shell_end();
}

function tenant_simple_module_v3(App $app,array $u,array $t,string $module):void
{
    $definitions=['categorias'=>['Categorías','categories',['name'=>'Nombre','sort_order'=>'Orden']],'delivery'=>['Zonas de delivery','delivery_zones',['name'=>'Zona','price'=>'Precio','min_order'=>'Compra mínima']],'cupones'=>['Cupones','coupons',['code'=>'Código','type'=>'Tipo','value'=>'Valor','min_order'=>'Compra mínima','max_uses'=>'Usos máximos','starts_at'=>'Inicio','ends_at'=>'Fin']]];
    [$title,$table,$fields]=$definitions[$module];
    if(is_post()){
        verify_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
        try{
            if($action==='toggle'&&$id){$app->exec("UPDATE $table SET is_active=1-is_active WHERE id=? AND tenant_id=?",[$id,$t['id']]);flash('success','Estado actualizado.');}
            elseif($action==='delete'&&$id){$app->exec("DELETE FROM $table WHERE id=? AND tenant_id=?",[$id,$t['id']]);flash('success','Registro eliminado.');}
            else{
                $columns=[];$values=[];
                foreach($fields as $key=>$label){$value=trim((string)($_POST[$key]??''));if(in_array($key,['name','code','price','value'],true)&&$value==='')throw new RuntimeException('Completa los campos obligatorios.');if($key==='code')$value=strtoupper($value);if($key==='type')$value=$value==='fixed'?'fixed':'percent';if(in_array($key,['price','min_order','value'],true)){$value=(float)$value;if($value<0)throw new RuntimeException('Los montos no pueden ser negativos.');}if(in_array($key,['sort_order','max_uses'],true)){$value=$value===''?null:(int)$value;if($value!==null&&$value<0)throw new RuntimeException('Los valores enteros no pueden ser negativos.');}if(in_array($key,['starts_at','ends_at'],true))$value=$value?str_replace('T',' ',$value).':00':null;$columns[]=$key;$values[]=$value;}
                if($table==='coupons'&&($_POST['type']??'percent')==='percent'&&(float)($_POST['value']??0)>100)throw new RuntimeException('El descuento porcentual no puede superar 100%.');
                if($table==='categories'){$columns[]='slug';$values[]=slugify((string)$_POST['name']);}
                if($id){$sets=implode(',',array_map(fn($column)=>$column.'=?',$columns));$app->exec("UPDATE $table SET $sets WHERE id=? AND tenant_id=?",array_merge($values,[$id,$t['id']]));}
                else{$app->exec("INSERT INTO $table (tenant_id,".implode(',',$columns).') VALUES (?,'.implode(',',array_fill(0,count($columns),'?')).')',array_merge([$t['id']],$values));}
                flash('success','Registro guardado.');
            }
        }catch(Throwable $exception){flash('error','No se pudo completar la acción: '.$exception->getMessage());}
        redirect(url('admin/'.$module));
    }
    $edit=!empty($_GET['edit'])?$app->one("SELECT * FROM $table WHERE id=? AND tenant_id=?",[(int)$_GET['edit'],$t['id']]):null;$rows=$app->all("SELECT * FROM $table WHERE tenant_id=? ORDER BY id DESC",[$t['id']]);
    admin_shell_start($title,$u,$t,$module);echo '<div class="split"><section class="card admin-card"><h2>'.($edit?'Editar':'Agregar').'</h2><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)($edit['id']??0).'">';
    foreach($fields as $key=>$label){if($key==='type')echo '<div class="form-group"><label>Tipo</label><select class="input" name="type"><option value="percent">Porcentaje</option><option value="fixed" '.(($edit['type']??'')==='fixed'?'selected':'').'>Monto fijo</option></select></div>';else{$type=in_array($key,['price','min_order','value','sort_order','max_uses'],true)?'number':(in_array($key,['starts_at','ends_at'],true)?'datetime-local':'text');$value=$edit[$key]??'';if($type==='datetime-local'&&$value)$value=str_replace(' ','T',substr((string)$value,0,16));echo field($label,$key,$value,in_array($key,['name','code','price','value'],true),$type,in_array($key,['price','min_order','value'],true)?'0.01':'1');}}
    echo '<button class="btn btn-block">Guardar</button></form></section><section class="card admin-card"><h2>Registros</h2><div class="table-wrap"><table class="table"><tr>';foreach($fields as $label)echo '<th>'.e($label).'</th>';echo '<th>Acciones</th></tr>';
    foreach($rows as $row){echo '<tr>';foreach(array_keys($fields) as $key)echo '<td>'.e($row[$key]??'').'</td>';echo '<td><a class="btn btn-light" href="?edit='.(int)$row['id'].'">Editar</a><form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$row['id'].'"><button class="btn btn-light" name="action" value="toggle">'.($row['is_active']?'Desactivar':'Activar').'</button><button class="btn btn-danger" name="action" value="delete" onclick="return confirm(\'¿Eliminar este registro?\')">Eliminar</button></form></td></tr>';}
    echo '</table></div></section></div>';admin_shell_end();
}

