    foreach($rows as $row)echo '<article class="content-admin-row">'.($row['image']?'<img src="'.e($row['image']).'" alt="'.e($row['title']).'">':'').'<div><span class="tag">'.e($row['section_key']).'</span><strong>'.e($row['title']).'</strong><small>'.e($row['body']).'</small><a class="btn btn-light" href="?edit='.(int)$row['id'].'">Editar</a><form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$row['id'].'"><button class="btn btn-light" name="action" value="toggle">'.($row['is_active']?'Desactivar':'Activar').'</button><button class="btn btn-danger" name="action" value="delete" onclick="return confirm(\'¿Eliminar este contenido?\')">Eliminar</button></form></div></article>';
