function tenant_kitchen_v4(App $app,array $u,array $t):void
{
    if(is_post()){
        verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');
        $transitions=['confirm'=>['new','confirmed'],'prepare'=>['confirmed','preparing'],'ready'=>['preparing','ready'],'pickup_delivered'=>['ready','delivered']];
        if($id&&isset($transitions[$action])){
            [$from,$to]=$transitions[$action];$order=$app->one('SELECT id,order_number,status,delivery_type FROM orders WHERE id=? AND tenant_id=?',[$id,$t['id']]);
            $pickupAllowed=$action!=='pickup_delivered'||($order&&$order['delivery_type']==='pickup');
            if($order&&$order['status']===$from&&$pickupAllowed){$app->exec('UPDATE orders SET status=? WHERE id=? AND tenant_id=? AND status=?',[$to,$id,$t['id'],$from]);audit($app,$t['id'],$u['id'],'kitchen_'.$action,'order',$id);flash('success','Pedido #'.$order['order_number'].' actualizado.');}
            else flash('error','El pedido cambió de estado. La pantalla fue actualizada.');
        }
        redirect(url('admin/cocina'));
    }
    $orders=$app->all("SELECT *,TIMESTAMPDIFF(MINUTE,created_at,NOW()) age_minutes FROM orders WHERE tenant_id=? AND status IN ('new','confirmed','preparing','ready') ORDER BY FIELD(status,'new','confirmed','preparing','ready'),created_at ASC LIMIT 80",[$t['id']]);
