    foreach($orders as $order){$items=$app->all('SELECT product_name,quantity,unit_label,options_json,notes FROM order_items WHERE order_id=? ORDER BY id',[$order['id']]);echo '<article class="card ops-card is-'.e(ui_label_qa((string)$order['status'])).'"><div class="ops-card-head"><div><span class="tag">'.e($labels[$order['status']]??$order['status']).'</span><h2>Pedido #'.e($order['order_number']).'</h2><small class="muted">'.e($order['customer_name']).' · '.e(date('H:i',strtotime($order['created_at']))).(!empty($order['scheduled_at'])?' · Programado '.e(date('d/m H:i',strtotime($order['scheduled_at']))):'').'</small></div><span class="ops-time">'.(int)$order['age_minutes'].' min</span></div><ul class="ops-items">';foreach($items as $item)echo '<li><div><strong>'.e($item['product_name']).'</strong>'.order_item_details_html($item).'</div><span>'.e($item['quantity']).' '.e($item['unit_label']).'</span></li>';echo '</ul>';if($order['notes'])echo '<div class="ops-notes"><strong>Notas:</strong> '.nl2br(e($order['notes'])).'</div>';echo '<div class="ops-actions"><a class="btn btn-light" href="'.url('admin/pedidos?view='.(int)$order['id']).'">Ver detalle</a>';
        if(isset($next[$order['status']])){[$action,$label]=$next[$order['status']];echo '<form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$order['id'].'"><button class="btn btn-accent" name="action" value="'.e($action).'">'.e($label).'</button></form>';}
