}

function tenant_delivery_board_v4(App $app,array $u,array $t):void
{
    if(is_post()){
        verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$transitions=['dispatch'=>['ready','sent'],'delivered'=>['sent','delivered']];
        if($id&&isset($transitions[$action])){[$from,$to]=$transitions[$action];$order=$app->one("SELECT id,status FROM orders WHERE id=? AND tenant_id=? AND delivery_type IN ('delivery','coordinated')",[$id,$t['id']]);if($order&&$order['status']===$from){$app->exec('UPDATE orders SET status=? WHERE id=? AND tenant_id=? AND status=?',[$to,$id,$t['id'],$from]);audit($app,$t['id'],$u['id'],'delivery_'.$action,'order',$id);flash('success','Entrega actualizada.');}else flash('error','La entrega cambió de estado. La pantalla fue actualizada.');}
        redirect(url('admin/repartidor'));
    }
    $orders=$app->all("SELECT o.*,z.name zone_name,TIMESTAMPDIFF(MINUTE,o.updated_at,NOW()) age_minutes FROM orders o LEFT JOIN delivery_zones z ON z.id=o.delivery_zone_id WHERE o.tenant_id=? AND o.delivery_type IN ('delivery','coordinated') AND o.status IN ('ready','sent') ORDER BY FIELD(o.status,'ready','sent'),o.updated_at ASC LIMIT 80",[$t['id']]);$labels=['ready'=>'Lista para salir','sent'=>'En camino'];
