    foreach($orders as $order){$digits=preg_replace('/\D+/','',(string)$order['customer_phone']);$wa=strlen($digits)===8?'506'.$digits:$digits;$maps='https://www.google.com/maps/search/?api=1&query='.rawurlencode((string)$order['address']);echo '<article class="card ops-card is-'.e(ui_label_qa((string)$order['status'])).'"><div class="ops-card-head"><div><span class="tag">'.e($labels[$order['status']]??$order['status']).'</span><h2>Pedido #'.e($order['order_number']).'</h2><small class="muted">'.e($order['zone_name']??'Envío coordinado').(!empty($order['scheduled_at'])?' · Programado '.e(date('d/m H:i',strtotime($order['scheduled_at']))):'').'</small></div><span class="ops-time">'.(int)$order['age_minutes'].' min</span></div><div><strong>'.e($order['customer_name']).'</strong><br><a href="tel:'.e($digits).'">'.e($order['customer_phone']).'</a></div><div class="delivery-address">'.nl2br(e($order['address']?:'Dirección pendiente de coordinación')).(!empty($order['address_reference'])?'<br><strong>Referencia:</strong> '.nl2br(e($order['address_reference'])):'').'</div><p><strong>Cobro:</strong> '.money((float)$order['total']).' · '.e($order['payment_method']).'</p>';if($order['notes'])echo '<div class="ops-notes"><strong>Notas:</strong> '.nl2br(e($order['notes'])).'</div>';echo '<div class="ops-actions"><a class="btn btn-light" target="_blank" rel="noopener" href="'.e($maps).'">Abrir mapa</a>'.($wa?'<a class="btn btn-light" target="_blank" rel="noopener" href="https://wa.me/'.e($wa).'">WhatsApp</a>':'').'<a class="btn btn-light" href="'.url('admin/pedidos?view='.(int)$order['id']).'">Detalle</a><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$order['id'].'">';if($order['status']==='ready')echo '<button class="btn btn-accent" name="action" value="dispatch">Marcar en camino</button>';else echo '<button class="btn btn-accent" name="action" value="delivered">Marcar entregado</button>';echo '</form></div></article>';
    }
    if(!$orders)echo '<div class="card empty">No hay entregas pendientes.</div>';echo '</div>';admin_shell_end();
}

