            elseif(in_array($action,['toggle_option','delete_option'],true)){$id=(int)($_POST['id']??0);$sql=$action==='delete_option'?'DELETE o FROM product_options o JOIN product_option_groups g ON g.id=o.group_id WHERE o.id=? AND g.product_id=? AND g.tenant_id=?':'UPDATE product_options o JOIN product_option_groups g ON g.id=o.group_id SET o.is_active=1-o.is_active WHERE o.id=? AND g.product_id=? AND g.tenant_id=?';$app->exec($sql,[$id,$productId,$t['id']]);flash('success','Opción actualizada.');}
