    $editGroup=!empty($_GET['edit_group'])?$app->one('SELECT * FROM product_option_groups WHERE id=? AND product_id=? AND tenant_id=?',[(int)$_GET['edit_group'],$productId,$t['id']]):null;$editOption=!empty($_GET['edit_option'])?$app->one('SELECT o.* FROM product_options o JOIN product_option_groups g ON g.id=o.group_id WHERE o.id=? AND g.product_id=? AND g.tenant_id=?',[(int)$_GET['edit_option'],$productId,$t['id']]):null;$groups=$app->all('SELECT * FROM product_option_groups WHERE product_id=? AND tenant_id=? ORDER BY sort_order,id',[$productId,$t['id']]);$options=$app->all('SELECT o.*,g.name group_name FROM product_options o JOIN product_option_groups g ON g.id=o.group_id WHERE g.product_id=? AND g.tenant_id=? ORDER BY g.sort_order,o.sort_order,o.id',[$productId,$t['id']]);$byGroup=[];foreach($options as $option)$byGroup[$option['group_id']][]=$option;
    echo '<p><a class="btn btn-light" href="'.url('admin/opciones').'">← Cambiar producto</a> <a class="btn btn-light" href="'.url('admin/productos?edit='.$productId).'">Editar producto</a></p><div class="section-head"><div><span class="tag">'.(($product['product_type']??'simple')==='combo'?'COMBO':'PRODUCTO').'</span><h1>'.e($product['name']).'</h1></div></div><div class="split"><section class="card admin-card"><h2>'.($editGroup?'Editar':'Nuevo').' grupo</h2><form method="post">'.csrf_field().'<input type="hidden" name="product_id" value="'.$productId.'"><input type="hidden" name="action" value="save_group"><input type="hidden" name="group_id" value="'.(int)($editGroup['id']??0).'">'.field('Nombre del grupo','name',$editGroup['name']??'',true).'<div class="form-group"><label>Selección</label><select class="input" name="type"><option value="single">Una opción</option><option value="multiple" '.(($editGroup['type']??'')==='multiple'?'selected':'').'>Varias opciones</option></select></div><label><input type="checkbox" name="is_required" '.(($editGroup['is_required']??0)?'checked':'').'> Selección obligatoria</label><div class="split" style="margin-top:15px">'.field('Mínimo','min_select',$editGroup['min_select']??0,true,'number','1').field('Máximo','max_select',$editGroup['max_select']??1,true,'number','1').'</div>'.field('Orden','sort_order',$editGroup['sort_order']??0,true,'number','1').'<button class="btn btn-block">Guardar grupo</button></form></section><section class="card admin-card"><h2>'.($editOption?'Editar':'Nueva').' opción</h2>';if(!$groups)echo '<div class="empty">Primero crea un grupo.</div>';else{echo '<form method="post">'.csrf_field().'<input type="hidden" name="product_id" value="'.$productId.'"><input type="hidden" name="action" value="save_option"><input type="hidden" name="option_id" value="'.(int)($editOption['id']??0).'"><div class="form-group"><label>Grupo</label><select class="input" name="group_id">';foreach($groups as $group)echo '<option value="'.(int)$group['id'].'" '.(($editOption['group_id']??0)==$group['id']?'selected':'').'>'.e($group['name']).'</option>';echo '</select></div>'.field('Nombre de opción','name',$editOption['name']??'',true).field('Precio adicional','price_delta',$editOption['price_delta']??0,true,'number','0.01').'<div class="form-group"><label>Producto relacionado (opcional)</label><select class="input" name="linked_product_id"><option value="">Ninguno</option>';foreach($products as $row)if((int)$row['id']!==$productId)echo '<option value="'.(int)$row['id'].'" '.(($editOption['linked_product_id']??0)==$row['id']?'selected':'').'>'.e($row['name']).'</option>';echo '</select></div>'.field('Orden','sort_order',$editOption['sort_order']??0,true,'number','1').'<button class="btn btn-block">Guardar opción</button></form>';}echo '</section></div><section style="margin-top:22px">';
    foreach($groups as $group){echo '<article class="card admin-card option-group-admin"><div class="section-head"><div><span class="tag">'.($group['type']==='single'?'UNA OPCIÓN':'VARIAS OPCIONES').'</span><h2>'.e($group['name']).'</h2><small class="muted">'.($group['is_required']?'Obligatorio':'Opcional').' · mínimo '.(int)$group['min_select'].' · máximo '.(int)$group['max_select'].'</small></div><div><a class="btn btn-light" href="?product='.$productId.'&edit_group='.(int)$group['id'].'">Editar</a><form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="product_id" value="'.$productId.'"><input type="hidden" name="id" value="'.(int)$group['id'].'"><button class="btn btn-light" name="action" value="toggle_group">'.($group['is_active']?'Desactivar':'Activar').'</button><button class="btn btn-danger" name="action" value="delete_group" onclick="return confirm(\'¿Eliminar el grupo y sus opciones?\')">Eliminar</button></form></div></div><div class="table-wrap"><table class="table"><tr><th>Opción</th><th>Adicional</th><th>Estado</th><th></th></tr>';foreach($byGroup[$group['id']]??[] as $option)echo '<tr><td>'.e($option['name']).'</td><td>+'.money((float)$option['price_delta']).'</td><td><span class="status '.(!$option['is_active']?'status-off':'').'">'.($option['is_active']?'Activa':'Inactiva').'</span></td><td><a class="btn btn-light" href="?product='.$productId.'&edit_option='.(int)$option['id'].'">Editar</a><form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="product_id" value="'.$productId.'"><input type="hidden" name="id" value="'.(int)$option['id'].'"><button class="btn btn-light" name="action" value="toggle_option">Alternar</button><button class="btn btn-danger" name="action" value="delete_option" onclick="return confirm(\'¿Eliminar esta opción?\')">Eliminar</button></form></td></tr>';echo '</table></div></article>';}
    if(!$groups)echo '<div class="card empty">Este producto todavía no tiene grupos de opciones.</div>';echo '</section>';admin_shell_end();
}
